local function elemental(def)for _,t in ipairs(def.tags or{})do if t=="elemental"or t=="all"then return true end end return false end
local function mage_spells(ctx)local r={};for _,id in ipairs(ctx:collectible_cards())do local d=ctx:card_definition(id);if d.type=="spell"and d.class=="mage"then r[#r+1]=id end end;return r end
local function stone(id,name,text,count,next_id)local x={id=id,name=name,text=text,set="LOOTAPALOOZA",type="spell",class="mage",collectible=false,rarity="rare",spell_school="fire",cost=2};x.on_play=function(ctx,self)ctx:set_data(self,"ruby_left",count);ctx:continue_with("ruby_next")end;x.ruby_next=function(ctx,self)if(ctx:get_data(self,"ruby_left")or 0)<=0 or #ctx:hand(ctx:controller(self))>=10 then return end;local pool=mage_spells(ctx);if #pool>0 then ctx:random_value(pool,"ruby_add")end end;x.ruby_add=function(ctx,self,cid)ctx:give_card(ctx:controller(self),cid);ctx:set_data(self,"ruby_left",ctx:get_data(self,"ruby_left")-1);ctx:continue_with("ruby_next")end;if next_id then x.triggers={{event="card_played",timing="after",active_zones={"hand"},condition=function(ctx,self,event)return event.player==ctx:controller(self)and elemental(ctx:card_definition(ctx:entity(event.entity).card_id))end,effect=function(ctx,self)local n=(ctx:get_data(self,"ruby_elementals")or 0)+1;if n>=2 then ctx:set_data(self,"ruby_elementals",0);ctx:transform_preserving_scripts(self,next_id)else ctx:set_data(self,"ruby_elementals",n)end end}}end;return x end
local card=stone("LOOT_103","Lesser Ruby Spellstone","Add 1 random Mage spell to your hand. <i>(Play 2 Elementals to upgrade.)</i>",1,"LOOT_103t1");card.collectible=true;card.tokens={stone("LOOT_103t1","Ruby Spellstone","Add 2 random Mage spells to your hand.",2,"LOOT_103t2"),stone("LOOT_103t2","Greater Ruby Spellstone","Add 3 random Mage spells to your hand.",3,nil)};return card
